require_once __DIR__.'/../includes/bootstrap.php';$user=require_login();$workspace=require_permission('build_dashboard');if(!plan_limits($workspace)['saved_insights']){http_response_code(403);exit('Saved Insights tersedia pada Pro atau Business.');}if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Gunakan POST.');}verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$st=$GLOBALS['pdo']->prepare('DELETE FROM saved_insights WHERE id=? AND workspace_id=?');$st->execute([$id,$workspace['id']]);if($st->rowCount())audit_log('insight.deleted','saved_insight',(int)$id);flash($st->rowCount()?'success':'warning',$st->rowCount()?'Insight dihapus.':'Insight tidak ditemukan.');redirect('insights/index.php');
